import{_ as a,C as n,o as e,c as i,a3 as t,b as d,w as r,a as s,E as c,a4 as g}from"./chunks/framework.BzWmN0d8.js";const f=JSON.parse('{"title":"简介","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/introduction.md","filePath":"zh/guide/introduction.md","lastUpdated":1788629526000}'),E={name:"zh/guide/introduction.md"};function h(B,o,u,A,p,m){const l=n("Mermaid");return e(),i("div",null,[o[1]||(o[1]=t('<h1 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h1><p><code>lograil</code> 是一个高性能、安全的日志库，面向 <strong>Electron</strong>（主进程 + 渲染进程）、<strong>Node.js</strong> 与 <strong>Web</strong>。它提供开箱即用的零配置 <code>logger</code>，可自动识别运行环境，并附带一套分层的过滤器、处理器、格式化器与传输器管线，可按需扩展。</p><p>本页介绍 <code>lograil</code> 是什么、为何存在、何时该用它，以及贯穿各篇指南的核心概念。如果你只想立刻开始记录日志，请直接跳到 <a href="./getting-started">快速开始</a>。</p><h2 id="为何选择-lograil" tabindex="-1">为何选择 lograil <a class="header-anchor" href="#为何选择-lograil" aria-label="Permalink to &quot;为何选择 lograil&quot;">​</a></h2><p>多数日志库把 Electron 当作事后补丁：你得手写 IPC、在多个进程间重复配置，还得祈祷渲染进程的日志真的能落盘。<code>lograil</code> 从一开始就为这种现实而设计：</p><ul><li><strong>一个 logger，跑遍所有运行时。</strong> 同样的 <code>import { logger } from &#39;lograil&#39;</code> 在主进程、渲染进程、Node 与浏览器中都能原样运行。运行时适配器会自动探测所处环境，并绑定正确的传输器。</li><li><strong>Electron 下默认安全。</strong> 渲染进程的日志通过 IPC 转发到主进程——它们绝不会在不受信任的上下文中触碰文件系统。这契合 Electron 的 <code>contextIsolation</code> + preload 安全模型（见 <a href="./runtime-electron">Electron</a>）。</li><li><strong>结构化，而非字符串拼接。</strong> 每条日志都是一个被冻结的 <code>LogEntry</code>，携带级别、消息、时间戳、<code>context</code>（持久化的请求级字段）、<code>metadata</code>（由处理器注入的单条条目细节），以及任意结构化字段。传输器可将其渲染为 JSON、控制台行或实时 UI，无需重新解析。详见 <a href="./context">上下文与元数据</a>。</li><li><strong>可组合的管线。</strong> 过滤 → 处理 → 格式化 → 传输。无需 fork 库即可加入采样、脱敏或自定义字段。</li><li><strong>热路径安全。</strong> 日志调用绝不会向你的业务代码抛出异常。某个传输器或订阅者出错会被隔离并上报，绝不会中断调用方。</li></ul><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>你正在构建 <strong>Electron 应用</strong>，希望主进程与渲染进程的日志统一写入文件和控制台，而无需手写 IPC。</li><li>你需要 <strong>结构化日志</strong>（级别、上下文、字段），且要能跨进程、跨运行时保留。</li><li>你需要 <strong>可插拔的输出</strong>——文件、控制台、OpenTelemetry、应用内实时视图——统一在单一 API 之后。</li><li>你在意 <strong>性能与安全</strong>，尤其是在延迟敏感的热路径上。</li></ul><p>如果你只是给 Node 脚本加一个极简的 <code>console.log</code> 封装，<code>lograil</code> 可能超出所需。但对于任何多进程、多运行时或面向生产的环境，它都物有所值。</p><h2 id="核心概念一览" tabindex="-1">核心概念一览 <a class="header-anchor" href="#核心概念一览" aria-label="Permalink to &quot;核心概念一览&quot;">​</a></h2><p><code>lograil</code> 以管线方式组织。一条日志会依次经过以下阶段：</p>',11)),(e(),d(g,null,{default:r(()=>[c(l,{id:"mermaid-76",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%E4%BD%A0%E7%9A%84%E4%BB%A3%E7%A0%81%5D%20--%3E%20B%5BLogger%5D%0A%20%20B%20--%3E%20C%5B%E7%AE%A1%E7%BA%BF%3A%20%E8%BF%87%E6%BB%A4%E5%99%A8%20%2F%20%E5%A4%84%E7%90%86%E5%99%A8%20%2F%20%E6%A0%BC%E5%BC%8F%E5%8C%96%E5%99%A8%5D%0A%20%20C%20--%3E%20D%5B%E4%BC%A0%E8%BE%93%E5%99%A8%5D%0A%20%20D%20--%3E%20E%5B%E6%8E%A7%E5%88%B6%E5%8F%B0%20%2F%20%E6%96%87%E4%BB%B6%20%2F%20OTLP%20%2F%20%E5%AE%9E%E6%97%B6%20UI%5D%0A%20%20F%5B%E4%B8%8A%E4%B8%8B%E6%96%87%5D%20-.enrich.-%3E%20B%0A%20%20G%5B%E8%BF%90%E8%A1%8C%E6%97%B6%E9%80%82%E9%85%8D%E5%99%A8%5D%20-.bind.-%3E%20D%0A%20%20H%5B%E6%8F%92%E4%BB%B6%5D%20-.extend.-%3E%20B%0A"})]),fallback:r(()=>[...o[0]||(o[0]=[s(" Loading... ",-1)])]),_:1})),o[2]||(o[2]=t('<ul><li><strong>LogEntry</strong> —— 单条日志事件的不可变、冻结记录：<code>level</code>、<code>message</code>、<code>timestamp</code>、<code>context</code>、<code>fields</code> 及元数据。它以引用方式共享，创建后绝不可修改。</li><li><strong>Level</strong> —— <code>trace</code> &lt; <code>debug</code> &lt; <code>info</code> &lt; <code>warn</code> &lt; <code>error</code> &lt; <code>fatal</code>。logger 与每个传输器都可设置各自的阈值。</li><li><strong>Context</strong> —— 通过异步本地存储自动附加到每条日志的环境键值数据（请求 id、用户 id、会话），无需在每次调用中层层传递。</li><li><strong>Pipeline</strong> —— 有序的 <strong>过滤器</strong>（丢弃或保留）、<strong>处理器</strong>（富集/脱敏/采样）与 <strong>格式化器</strong>（将日志条目转为字符串或字节）链，在日志发出前对其进行塑形。</li><li><strong>Transports</strong> —— 目的地：控制台、滚动文件、OpenTelemetry（OTLP）、应用内实时流，或你自定义的传输器。一个 logger 可拥有多个。</li><li><strong>运行时适配器</strong> —— 探测环境（Electron 主/渲染进程、Node、Web）并绑定正确的默认值，使同一份代码处处可运行。</li><li><strong>插件</strong> —— 以横切方式扩展 logger（链路追踪、指标、自定义钩子），而无需改动核心。</li></ul><p>这些概念在 <a href="./architecture">架构</a> 中有更深入的阐述。<a href="/lograil/zh/api/">API 参考</a> 记录了每个类型与方法。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./getting-started">快速开始</a> —— 安装并发出你的第一条结构化日志。</li><li><a href="./configuration">配置</a> —— 级别、管线与传输器。</li><li><a href="./transports">传输器</a> —— 内置与自定义目的地。</li><li><a href="./runtime-electron">Electron</a> —— 安全的主/渲染进程日志配置。</li></ul>',4))])}const P=a(E,[["render",h]]);export{f as __pageData,P as default};
